{
  "category_edits": [
    {
      "category": "sequence_modeling",
      "rationale": "Halve the configured causal context length, rounding up, for all four datasets. Existing truncation retains recent interactions in chronological order, and saved maxlen metadata applies the same limit during prediction. Shorter histories may reduce stale-interest interference and recurrent computation while preserving all other model and training settings.",
      "edits": [
        {
          "find": "MAXLEN        = int(os.environ.get(\"GRU4REC_MAXLEN\", \"128\"))",
          "replace": "MAXLEN        = max(1, (int(os.environ.get(\"GRU4REC_MAXLEN\", \"128\")) + 1) // 2)"
        }
      ]
    }
  ],
  "change_summary": "Reduce default context from 128 to 64 interactions consistently across training, validation and generated prediction through existing checkpoint metadata."
}
